/**
 * Config plugin: sign local Android release builds with your own upload key.
 *
 * android/ is generated by `npx expo prebuild` (Continuous Native Generation), so the
 * template's `android/app/build.gradle` cannot be edited by hand. This plugin patches it
 * during prebuild so that `buildTypes.release` uses a `release` signing config built from
 * these Gradle properties (or environment variables of the same name):
 *
 *   VOICE_UPLOAD_STORE_FILE      absolute path to the keystore (scripts/create-upload-keystore.sh)
 *   VOICE_UPLOAD_STORE_PASSWORD
 *   VOICE_UPLOAD_KEY_ALIAS
 *   VOICE_UPLOAD_KEY_PASSWORD
 *
 * Put them in ~/.gradle/gradle.properties, never in the repository.
 *
 * When any of them is missing, the template's debug signing is kept, so `npx expo run:android`
 * and contributors without a key keep working. EAS Build injects its own signing config and is
 * unaffected. The patch is idempotent: running prebuild again replaces the generated lines.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const TAG = 'voice-release-signing';
const BEGIN = `// @generated begin ${TAG} - expo prebuild (DO NOT MODIFY)`;
const END = `// @generated end ${TAG}`;
const RELEASE_LINE_SUFFIX = `// @${TAG}`;
const DEBUG_SIGNING_LINE = 'signingConfig signingConfigs.debug';

const HELPERS = `${BEGIN}
def voiceSigningProp = { String name ->
    def value = findProperty(name) ?: System.getenv(name)
    return value ? value.toString() : null
}
def voiceReleaseSigning = [
    'VOICE_UPLOAD_STORE_FILE',
    'VOICE_UPLOAD_STORE_PASSWORD',
    'VOICE_UPLOAD_KEY_ALIAS',
    'VOICE_UPLOAD_KEY_PASSWORD',
].every { voiceSigningProp(it) }
${END}
`;

const SIGNING_CONFIG = `        ${BEGIN}
        if (voiceReleaseSigning) {
            release {
                def voiceStoreFile = file(voiceSigningProp('VOICE_UPLOAD_STORE_FILE'))
                if (!voiceStoreFile.exists()) {
                    throw new GradleException("VOICE_UPLOAD_STORE_FILE not found: \${voiceStoreFile}")
                }
                storeFile voiceStoreFile
                storePassword voiceSigningProp('VOICE_UPLOAD_STORE_PASSWORD')
                keyAlias voiceSigningProp('VOICE_UPLOAD_KEY_ALIAS')
                keyPassword voiceSigningProp('VOICE_UPLOAD_KEY_PASSWORD')
            }
        }
        ${END}
`;

const RELEASE_LINE = `signingConfig voiceReleaseSigning ? signingConfigs.release : signingConfigs.debug ${RELEASE_LINE_SUFFIX}`;

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Remove everything this plugin added, restoring the template's lines. */
function stripReleaseSigning(contents) {
  const block = new RegExp(`[ \\t]*${escapeRegExp(BEGIN)}[\\s\\S]*?${escapeRegExp(END)}[ \\t]*\\r?\\n?`, 'g');
  return contents.replace(block, '').split(RELEASE_LINE).join(DEBUG_SIGNING_LINE);
}

/** Find the index of the `}` closing the block whose `{` is at `openIndex`. */
function findBlockEnd(contents, openIndex) {
  let depth = 0;
  for (let i = openIndex; i < contents.length; i++) {
    if (contents[i] === '{') depth++;
    else if (contents[i] === '}' && --depth === 0) return i;
  }
  return -1;
}

/**
 * Pure transform of android/app/build.gradle (Groovy). Throws if the template no longer
 * has the expected shape, so a changed Expo template fails prebuild loudly instead of
 * silently producing a debug-signed release.
 */
function applyReleaseSigning(source) {
  let contents = stripReleaseSigning(source);
  const fail = (what) => {
    throw new Error(`[with-release-signing] Could not find ${what} in android/app/build.gradle; update plugins/with-release-signing.js for the new template.`);
  };

  // 1. Helpers at the top level, right before `android {`.
  const androidMatch = /^android\s*\{/m.exec(contents);
  if (!androidMatch) fail('`android {`');
  contents = contents.slice(0, androidMatch.index) + HELPERS + contents.slice(androidMatch.index);

  // 2. The release signing config, first entry of `signingConfigs {`.
  const signingMatch = /^([ \t]*)signingConfigs\s*\{[ \t]*\r?\n/m.exec(contents);
  if (!signingMatch) fail('`signingConfigs {`');
  const signingInsertAt = signingMatch.index + signingMatch[0].length;
  contents = contents.slice(0, signingInsertAt) + SIGNING_CONFIG + contents.slice(signingInsertAt);

  // 3. `buildTypes { … release { … signingConfig signingConfigs.debug … } }`.
  const buildTypesMatch = /^[ \t]*buildTypes\s*\{/m.exec(contents);
  if (!buildTypesMatch) fail('`buildTypes {`');
  const buildTypesOpen = buildTypesMatch.index + buildTypesMatch[0].length - 1;
  const buildTypesEnd = findBlockEnd(contents, buildTypesOpen);
  if (buildTypesEnd < 0) fail('the end of `buildTypes {`');

  const releaseRe = /^[ \t]*release\s*\{/m;
  const buildTypesBody = contents.slice(buildTypesOpen, buildTypesEnd);
  const releaseMatch = releaseRe.exec(buildTypesBody);
  if (!releaseMatch) fail('`buildTypes { release {`');
  const releaseOpen = buildTypesOpen + releaseMatch.index + releaseMatch[0].length - 1;
  const releaseEnd = findBlockEnd(contents, releaseOpen);
  if (releaseEnd < 0) fail('the end of `release {`');

  const releaseBody = contents.slice(releaseOpen, releaseEnd);
  const lineIndex = releaseBody.indexOf(DEBUG_SIGNING_LINE);
  if (lineIndex < 0) fail('`signingConfig signingConfigs.debug` in `buildTypes.release`');
  const newReleaseBody =
    releaseBody.slice(0, lineIndex) + RELEASE_LINE + releaseBody.slice(lineIndex + DEBUG_SIGNING_LINE.length);

  return contents.slice(0, releaseOpen) + newReleaseBody + contents.slice(releaseEnd);
}

const withReleaseSigning = (config) =>
  withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error('[with-release-signing] Only the Groovy android/app/build.gradle is supported.');
    }
    cfg.modResults.contents = applyReleaseSigning(cfg.modResults.contents);
    return cfg;
  });

module.exports = withReleaseSigning;
module.exports.applyReleaseSigning = applyReleaseSigning;
module.exports.stripReleaseSigning = stripReleaseSigning;
